  // School import (docs/api/phase-3-bulk-import.md) and setting a staff password.
  "schoolImport.card.title": "మీ ప్రస్తుత విద్యార్థులు, సిబ్బందిని తీసుకురండి",
  "schoolImport.card.body": "పాఠశాల ఇప్పటికే నడుస్తోందా? ఒక Excel ఫైల్ నింపండి, అందులో ఒక Staff షీట్, ప్రతి తరగతి, సెక్షన్‌కు ఒక్కో షీట్ ఉండాలి. అందరినీ ఒకేసారి చేర్చడానికి దాన్ని అప్‌లోడ్ చేయండి.",
